items.solution:
function verifyChain(leafCert, intermediateCert, trustedRootId, hostname) {
  if (leafCert.subject !== hostname) {
    return { valid: false, reason: 'hostname mismatch' };
  }
  if (intermediateCert.signedBy !== trustedRootId) {
    return { valid: false, reason: 'intermediate not signed by trusted root' };
  }
  if (leafCert.signedBy !== intermediateCert.subject) {
    return { valid: false, reason: 'leaf not signed by intermediate' };
  }
  return { valid: true, reason: 'chain verifies to a trusted root, hostname matches' };
}

