items.solution:
function hostnameMatches(certSubject, addressBarHost) {
  if (certSubject.startsWith('*.')) {
    const suffix = certSubject.slice(1);
    return (
      addressBarHost.endsWith(suffix) &&
      addressBarHost.split('.').length === certSubject.split('.').length
    );
  }
  return certSubject === addressBarHost;
}

